INSERT INTO _Locale ("LocaId","LocaText") VALUES ('z_arcanethief_N','Arcane Thief');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('z_arcanethief_D','Trained in the shadows and in the arcane: Arcane lore and Alchemy without the thief penalty (scrolls and potions), a knack for haste, blinding and illusion spells, but weaker with fire, summoning and battlefield magic, and slower to regain astral energy.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('MI_TA_M_Info','A thief from Grangor who stole a magister''s grimoire and, to everyone''s surprise, understood it. Quick with dagger and throwing knife, light on his feet, and able to learn almost any spell a battle mage can, though his astral reserves are smaller and slower to return.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('MI_TA_W_Info','A thief from Grangor who stole a magister''s grimoire and, to everyone''s surprise, understood it. Quick with dagger and throwing knife, light on her feet, and able to learn almost any spell a battle mage can, though her astral reserves are smaller and slower to return.');
